C=4
SRC={
'2':'śakrādayaḥ suragaṇā nihate’tivīrye / tasmindurātmani surāribale ca devyā | / tāṁ tuṣṭuvuḥ praṇatinamraśirodharāṁsā / vāgbhiḥ praharṣapulakodgamacārudehāḥ || 2||',
'3':'devyā yayā tatamidaṁ jagadātmaśaktyā / niḥśeṣadevagaṇaśaktisamūhamūrtyā | / tāmambikāmakhiladevamaharṣipūjyāṁ / bhaktyā natāḥ sma vidadhātu śubhāni sā naḥ || 3||',
'4':'yasyāḥ prabhāvamatulaṁ bhagavānananto / brahmā haraśca na hi vaktumalaṁ balaṁ ca | / sā caṇḍikākhilajagatparipālanāya / nāśāya cāśubhabhayasya matiṁ karotu || 4||',
'5':'yā śrīḥ svayaṁ sukṛtināṁ bhavaneṣvalakṣmīḥ / pāpātmanāṁ kṛtadhiyāṁ hṛdayeṣu buddhiḥ | / śraddhā satāṁ kulajanaprabhavasya lajjā / tāṁ tvāṁ natāḥ sma paripālaya devi viśvam || 5||',
'6':'kiṁ varṇayāma tava rūpamacintyametat / kiñcātivīryamasurakṣayakāri bhūri | / kiṁ cāhaveṣu caritāni tavāti yāni / sarveṣu devyasuradevagaṇādikeṣu || 6||',
'7':'hetuḥ samastajagatāṁ triguṇāpi doṣai- / rna jñāyase hariharādibhirapyapārā | / sarvāśrayākhilamidaṁ jagadaṁśabhūta- / mavyākṛtā hi paramā prakṛtistvamādyā || 7||',
'8':'yasyāḥ samastasuratā samudīraṇena / tṛptiṁ prayāti sakaleṣu makheṣu devi | / svāhāsi vai pitṛgaṇasya ca tṛptihetu- / ruccāryase tvamata eva janaiḥ svadhā ca || 8||',
'9':'yā muktiheturavicintyamahāvratā tvaṁ / abhyasyase suniyatendriyatattvasāraiḥ | / mokṣārthibhirmunibhirastasamastadoṣai- / rvidyāsi sā bhagavatī paramā hi devi || 9||',
'10':'śabdātmikā suvimalargyajuṣāṁ nidhāna- / mudgītharamyapadapāṭhavatāṁ ca sāmnām | / devi trayī bhagavatī bhavabhāvanāya / vārtāsi sarvajagatāṁ paramārtihantrī || 10||',
'11':'medhā’si devi viditākhilaśāstrasārā / durgāsi durgabhavasāgaranaurasaṅgā | / śrīḥ kaiṭabhārihṛdayaikakṛtādhivāsā / gaurī tvameva śaśimaulikṛtapratiṣṭhā || 11||',
'12':'īṣatsahāsamamalaṁ paripūrṇacandra- / bimbānukāri kanakottamakāntikāntam | / atyadbhutaṁ prahṛtamāttaruṣā tathāpi / vaktraṁ vilokya sahasā mahiṣāsureṇa || 12||',
'13':'dṛṣṭvā tu devi kupitaṁ bhrukuṭīkarāla- / mudyacchaśāṅkasadṛśacchavi yanna sadyaḥ | / prāṇān mumoca mahiṣastadatīva citraṁ / kairjīvyate hi kupitāntakadarśanena || 13||',
'14':'devi prasīda paramā bhavatī bhavāya / sadyo vināśayasi kopavatī kulāni | / vijñātametadadhunaiva yadastameta- / nnītaṁ balaṁ suvipulaṁ mahiṣāsurasya || 14||',
'15':'te sammatā janapadeṣu dhanāni teṣāṁ / teṣāṁ yaśāṁsi na ca sīdati dharmavargaḥ | / dhanyāsta eva nibhṛtātmajabhṛtyadārā / yeṣāṁ sadābhyudayadā bhavatī prasannā || 15||',
'16':'dharmyāṇi devi sakalāni sadaiva karmā- / ṇyatyādṛtaḥ pratidinaṁ sukṛtī karoti | / svargaṁ prayāti ca tato bhavatī prasādā- / llokatraye’pi phaladā nanu devi tena || 16||',
'17':'durge smṛtā harasi bhītimaśeṣajantoḥ / svasthaiḥ smṛtā matimatīva śubhāṁ dadāsi | / dāridryaduḥkhabhayahāriṇi kā tvadanyā / sarvopakārakaraṇāya sadārdracittā || 17||',
'18':'ebhirhatairjagadupaiti sukhaṁ tathaite / kurvantu nāma narakāya cirāya pāpam | / saṅgrāmamṛtyumadhigamya divaṁ prayāntu / matveti nūnamahitānvinihaṁsi devi || 18||',
'19':'dṛṣṭvaiva kiṁ na bhavatī prakaroti bhasma / sarvāsurānariṣu yatprahiṇoṣi śastram | / lokānprayāntu ripavo’pi hi śastrapūtā / itthaṁ matirbhavati teṣvahiteṣu sādhvī || 19||',
'20':'khaḍgaprabhānikaravisphuraṇaistathograiḥ / śūlāgrakāntinivahena dṛśo’surāṇām | / yannāgatā vilayamaṁśumadindukhaṇḍa- / yogyānanaṁ tava vilokayatāṁ tadetat || 20||',
'21':'durvṛttavṛttaśamanaṁ tava devi śīlaṁ / rūpaṁ tathaitadavicintyamatulyamanyaiḥ | / vīryaṁ ca hantṛ hṛtadevaparākramāṇāṁ / vairiṣvapi prakaṭitaiva dayā tvayettham || 21||',
'22':'kenopamā bhavatu te’sya parākramasya / rūpaṁ ca śatrubhayakāryatihāri kutra | / citte kṛpā samaraniṣṭhuratā ca dṛṣṭā / tvayyeva devi varade bhuvanatraye’pi || 22||',
'23':'trailokyametadakhilaṁ ripunāśanena / trātaṁ tvayā samaramūrdhani te’pi hatvā | / nītā divaṁ ripugaṇā bhayamapyapāstam / asmākamunmadasurāribhavaṁ namaste || 23||',
'24':'śūlena pāhi no devi pāhi khaḍgena cāmbike | / ghaṇṭāsvanena naḥ pāhi cāpajyāniḥsvanena ca || 24||',
'25':'prācyāṁ rakṣa pratīcyāṁ ca caṇḍike rakṣa dakṣiṇe | / bhrāmaṇenātmaśūlasya uttarasyāṁ tatheśvari || 25||',
'26':'saumyāni yāni rūpāṇi trailokye vicaranti te | / yāni cātyantaghorāṇi tai rakṣāsmāṁstathā bhuvam || 26||',
'27':'khaḍgaśūlagadādīni yāni cāstrāni te’mbike | / karapallavasaṅgīni tairasmānrakṣa sarvataḥ || 27||',
}
